  const { state: documentState, retry: retryDocument } = useDocument(fileRef, {
    onLoaded: document => setAnnouncement(`Loaded ${fileName(document)}.`),
    onFailed: (ref, kind) => setAnnouncement(kind === 'missing' ? `${fileName(ref)} was not found.` : `Loading ${fileName(ref)} failed.`),
  })
  const openFile = useCallback((node: GraphNode) => {
    if (node.kind !== 'file') return
    const ref: FileRef = { source: node.source, path: node.path }
    const pathname = fileToPathname(ref)
    returnContexts.current.set(pathname, { pathname: window.location.pathname, location: locationRef.current, focusId: node.id })
    pendingFocus.current = null
    if (window.location.pathname !== pathname) window.history.pushState(null, '', pathname)
    setLocation({ kind: 'file', ref })
    setAnnouncement(`Loading ${fileName(ref)}.`)
  }, [])

  const backToFolder = useCallback(() => {
    const current = locationRef.current
    if (current.kind !== 'file') return
    const context = returnContexts.current.get(fileToPathname(current.ref))
    if (context) {
      // Restore the exact browsing entry: no fit, no re-expansion, no layout reset.
      if (window.location.pathname !== context.pathname) window.history.pushState(null, '', context.pathname)
      setLocation(context.location)
      pendingFocus.current = context.focusId
    } else {
      // Direct link or reload: open the containing folder and reveal its ancestors.
      pendingFocus.current = nodeId(current.ref.source, current.ref.path)
      navigate(parentFolderOf(current.ref), { reveal: true })
    }
  }, [navigate])

  // Focus the originating file action once the browsing view has rendered it again.
  useEffect(() => {
    const id = pendingFocus.current
    if (!id || location.kind === 'file') return
    const selector = `[data-node-id="${CSS.escape(id)}"]`
    const target = document.querySelector<HTMLElement | SVGElement>(`${selector} .node-body, ${selector} .outline-name`)
    if (target) {
      pendingFocus.current = null
      target.focus()
    }
  })

  const index = data.status === 'ready' ? data.index : null
  const selectedRef = location.kind === 'folder' ? location.ref : null
  const selectedExists = index !== null && selectedRef !== null && folderExists(index, selectedRef)
  const selectedId = selectedExists && selectedRef ? refId(selectedRef) : null
  const visible = useMemo(() => (index ? visibleGraph(index, expanded) : { nodes: [], edges: [] }), [index, expanded])

  const select = useCallback((node: GraphNode) => {
    const ref = { source: node.source, path: node.path }
    if (sameRef(locationRef.current.kind === 'folder' ? locationRef.current.ref : null, ref)) return
    navigate(ref)
  }, [navigate])

  const toggleExpand = useCallback((node: GraphNode) => {
    if (!index) return
    if (expanded.has(node.id)) {
      setExpanded(collapseNode(index, expanded, node.id))
      const current = locationRef.current
      if (current.kind === 'folder' && descendantIds(index, node.id).includes(refId(current.ref))) {
        navigate({ source: node.source, path: node.path }, { replace: true })
      }
      setAnnouncement(`Collapsed ${node.name}.`)
    } else {
      setExpanded(new Set(expanded).add(node.id))
      setAnnouncement(`Expanded ${node.name}: ${describeCounts(childCounts(index, node.id))}`)
    }
  }, [index, expanded, navigate])

  const togglePin = useCallback((node: GraphNode) => {
    const wasPinned = layout.isPinned(node.id)
    layout.togglePin(node.id)
    setAnnouncement(`${wasPinned ? 'Unpinned' : 'Pinned'} ${node.name}.`)
  }, [layout])

  const reset = useCallback(() => {
    layout.reset()
    setExpanded(new Set())
    navigate(null)
    setAnnouncement('Reset: showing the Pi and Claude sources.')
  }, [layout, navigate])

  const toggleMode = useCallback(() => {
    setMode(previous => {
      const next = previous === 'graph' ? 'outline' : 'graph'
      setAnnouncement(next === 'outline' ? 'Outline view.' : 'Graph view.')
      return next
    })
  }, [])

  const ready = data.status === 'ready'
  const refreshing = data.status === 'ready' && data.refreshing
  const graphControlsEnabled = ready && mode === 'graph'
  const browsing = fileRef === null

  let missingNotice: React.ReactNode = null
  if (index && location.kind === 'unknown-source') {
    missingNotice = <>Source “{location.name}” does not exist. Only the Pi and Claude sources are available.</>
  } else if (index && location.kind === 'malformed') {
    missingNotice = <>This link is invalid and could not be read.</>
  } else if (index && selectedRef && !selectedExists) {
    missingNotice = <>Folder “{selectedRef.path || selectedRef.source}” was not found in {selectedRef.source}. It may have been renamed or removed.</>
  }

  return (
    <div className="app">
      <header className="app-header">
        <div className="app-title">
          <h1>MD Manager</h1>
          <p>Pi and Claude fixture folders as a containment graph. Read-only.</p>
        </div>
        <button type="button" className="button" onClick={() => void refresh()} disabled={!ready || refreshing} aria-busy={refreshing}>
          {refreshing ? 'Refreshing…' : 'Refresh'}
        </button>
      </header>

      <div className="visually-hidden" role="status" aria-live="polite">{announcement}</div>

      {data.status === 'ready' && data.refreshError && (
        <div className="banner banner-error" role="alert">
          Refresh failed: {data.refreshError} The graph still shows the previous listing, which may be outdated. Try Refresh again once the API and fixture folders are available.
        </div>
      )}

      <div className="navigation">
        <Breadcrumbs selected={selectedRef} file={fileRef} onNavigate={ref => navigate(ref, { reveal: true })} />
        {fileRef ? null : missingNotice ? (
          <div className="missing" role="alert">
            <p>{missingNotice}</p>
            <p className="missing-links">
              {selectedRef && location.kind === 'folder'
                ? <a href={folderToPathname({ source: selectedRef.source, path: '' })} onClick={event => { event.preventDefault(); navigate({ source: selectedRef.source, path: '' }, { reveal: true }) }}>Go to the {selectedRef.source} root</a>
                : <>
                    <a href="/Pi" onClick={event => { event.preventDefault(); navigate({ source: 'Pi', path: '' }, { reveal: true }) }}>Go to the Pi root</a>
                    <a href="/Claude" onClick={event => { event.preventDefault(); navigate({ source: 'Claude', path: '' }, { reveal: true }) }}>Go to the Claude root</a>
                  </>}
              <a href="/" onClick={event => { event.preventDefault(); navigate(null) }}>Home</a>
            </p>
          </div>
        ) : (
          <p className="folder-info" data-testid="folder-info">
            {index && selectedId
              ? describeCounts(childCounts(index, selectedId))
              : 'Two sources: Pi and Claude. Select a source or folder to see what it contains.'}
          </p>
        )}
      </div>

      {browsing && (
        <div className="toolbar" role="toolbar" aria-label="Graph controls">
          <button type="button" className="button" onClick={() => canvasRef.current?.zoomIn()} disabled={!graphControlsEnabled} aria-label="Zoom in">+</button>
          <button type="button" className="button" onClick={() => canvasRef.current?.zoomOut()} disabled={!graphControlsEnabled} aria-label="Zoom out">−</button>
          <button type="button" className="button" onClick={() => canvasRef.current?.fit()} disabled={!graphControlsEnabled}>Fit</button>
          <button type="button" className="button" onClick={reset} disabled={!ready}>Reset</button>
          <button type="button" className="button" onClick={toggleMode} disabled={!ready} aria-pressed={mode === 'outline'}>Outline</button>
        </div>
      )}

      <main className={browsing ? 'workspace' : 'workspace workspace-document'} aria-busy={browsing && data.status === 'loading'}>
        {fileRef && documentState && (
          <DocumentView fileRef={fileRef} state={documentState} onBack={backToFolder} onRetry={retryDocument} />
        )}
        {browsing && data.status === 'loading' && (
          <div className="placeholder">
            <p>Loading the Pi and Claude fixture folders…</p>
          </div>
        )}
        {browsing && data.status === 'error' && (
          <div className="placeholder" role="alert">
            <p>Unable to load the fixture folders. {data.message}</p>
            <p>Check that the API is running and both fixture folders are readable, then retry.</p>
            <button type="button" className="button" onClick={retry}>Retry</button>
          </div>
        )}
        {browsing && data.status === 'ready' && mode === 'graph' && (
          <GraphCanvas
            ref={canvasRef}
            layout={layout}
            index={data.index}
            nodes={visible.nodes}
            edges={visible.edges}
            expanded={expanded}
            selectedId={selectedId}
            viewRequest={viewRequest}
            handledRequest={handledRequest}
            viewStore={viewStore}
            onSelect={select}
            onOpenFile={openFile}
            onToggleExpand={toggleExpand}
            onTogglePin={togglePin}
          />
        )}
        {browsing && data.status === 'ready' && mode === 'outline' && (
          <Outline
            index={data.index}
            expanded={expanded}
            selectedId={selectedId}
            scrollRef={outlineScroll}
            onSelect={select}
            onOpenFile={openFile}
            onToggleExpand={toggleExpand}
          />
        )}
      </main>

      {browsing && mode === 'graph' && (
        <footer className="legend" aria-label="Legend">
          <ul>
            <li><svg viewBox="-16 -16 32 32" aria-hidden="true"><circle className="legend-source" r="11" /></svg>Source</li>
            <li><svg viewBox="-16 -16 32 32" aria-hidden="true"><path className="legend-directory" d="M -12 -9 h 7 l 3 3 h 14 v 15 h -24 z" /></svg>Folder</li>
            <li><svg viewBox="-16 -16 32 32" aria-hidden="true"><path className="legend-file" d="M -7 -11 h 9 l 5 5 v 17 h -14 z" /></svg>Markdown file</li>
            <li><svg viewBox="-16 -16 32 32" aria-hidden="true"><line className="legend-edge" x1="-13" y1="0" x2="8" y2="0" markerEnd="url(#contains-arrow)" /><path className="legend-edge-arrow" d="M 7 -4 L 13 0 L 7 4 z" /></svg>Contains (parent → child)</li>
            <li><svg viewBox="-16 -16 32 32" aria-hidden="true"><circle className="legend-pin" r="9" /><path className="legend-pin-glyph" d="M -3 -4 h 6 l -1 4 h -4 z M 0 0 v 6" /></svg>Pinned (dragged or P)</li>
          </ul>
          <p>Keyboard: Tab moves through nodes in outline order, Enter selects a folder or opens a file, → expands, ← collapses, P pins or unpins.</p>
        </footer>
      )}
    </div>
  )
}

export default App
import { useCallback, useEffect, useRef, useState } from 'react'
import { fileToPathname, type FileRef } from '../graph/model.ts'
import { DocumentError, fetchDocument, type DocumentErrorKind, type FileDocument } from './api.ts'

export type DocumentState =
  | { status: 'loading'; ref: FileRef }
  | { status: 'ready'; ref: FileRef; document: FileDocument }
  | { status: 'error'; ref: FileRef; kind: DocumentErrorKind; message: string }

type Settled = Exclude<DocumentState, { status: 'loading' }> & { requestKey: string }

type Events = {
  onLoaded?: (document: FileDocument) => void
  onFailed?: (ref: FileRef, kind: DocumentErrorKind) => void
}

/**
 * Loads the document for `ref` whenever it changes. Every request is tied to the ref (and attempt) that
 * started it and cancelled when the ref changes or clears, so a slow response (success or error) can never
 * be shown under another document's identity or reopen a document after navigating away.
 */
export function useDocument(ref: FileRef | null, events: Events = {}): { state: DocumentState | null; retry: () => void } {
  const [settled, setSettled] = useState<Settled | null>(null)
  const [attempt, setAttempt] = useState(0)
  const eventsRef = useRef(events)
  useEffect(() => { eventsRef.current = events })
  const key = ref ? fileToPathname(ref) : null
  const requestKey = key === null ? null : `${key}#${attempt}`

  useEffect(() => {
    if (!ref || requestKey === null) return
    const controller = new AbortController()
    const target = ref
    void (async () => {
      try {
        const document = await fetchDocument(target, controller.signal)
        if (controller.signal.aborted) return
        setSettled({ status: 'ready', ref: target, document, requestKey })
        eventsRef.current.onLoaded?.(document)
      } catch (error) {
        if (controller.signal.aborted) return
        const kind = error instanceof DocumentError ? error.kind : 'failed'
        const message = error instanceof DocumentError ? error.message : 'The file could not be loaded.'
        setSettled({ status: 'error', ref: target, kind, message, requestKey })
        eventsRef.current.onFailed?.(target, kind)
      }
    })()
    return () => controller.abort()
    // `requestKey` captures the ref's identity and the attempt; the ref object may be recreated on every parse.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [requestKey])

  const retry = useCallback(() => setAttempt(previous => previous + 1), [])

  // A settled result is only ever shown for the exact request it answered; anything else is loading.
  if (!ref || requestKey === null) return { state: null, retry }
  const state: DocumentState = settled && settled.requestKey === requestKey ? settled : { status: 'loading', ref }
  return { state, retry }
}
import { useEffect, useRef, useState, type KeyboardEvent } from 'react'
import { fileToPathname, type FileRef } from '../graph/model.ts'
import { Markdown } from './Markdown.tsx'
import type { DocumentState } from './useDocument.ts'

type Tab = 'rendered' | 'source'
const TABS: ReadonlyArray<{ id: Tab; label: string }> = [
  { id: 'rendered', label: 'Rendered' },
  { id: 'source', label: 'Source' },
]

type Props = {
  fileRef: FileRef
  state: DocumentState
  onBack: () => void
  onRetry: () => void
}


function baseName(path: string): string {
  return path.slice(path.lastIndexOf('/') + 1)
}

/** Read-only document shell: identity header, Back to folder, Rendered/Source tabs and the load states. */
export function DocumentView({ fileRef, state, onBack, onRetry }: Props) {
  const key = fileToPathname(fileRef)
  const name = baseName(fileRef.path)
  const headingRef = useRef<HTMLHeadingElement>(null)
  const tabRefs = useRef<Array<HTMLButtonElement | null>>([])
  const [tab, setTab] = useState<Tab>('rendered')
  const [tabKey, setTabKey] = useState(key)
  // Opening a different document always starts on Rendered.
  if (tabKey !== key) {
    setTabKey(key)
    setTab('rendered')
  }

  // Focus moves to the document entry point when a document is opened (not when switching tabs).
  useEffect(() => { headingRef.current?.focus() }, [key])

  const onTabKeyDown = (event: KeyboardEvent<HTMLButtonElement>) => {
    const index = TABS.findIndex(candidate => candidate.id === tab)
    let next: number | null = null
    if (event.key === 'ArrowRight' || event.key === 'ArrowDown') next = (index + 1) % TABS.length
    else if (event.key === 'ArrowLeft' || event.key === 'ArrowUp') next = (index - 1 + TABS.length) % TABS.length
    else if (event.key === 'Home') next = 0
    else if (event.key === 'End') next = TABS.length - 1
    if (next === null) return
    event.preventDefault()
    setTab(TABS[next].id)
    tabRefs.current[next]?.focus()
  }

  let panel: React.ReactNode
  if (state.status === 'loading') {
    panel = <p className="document-message">Loading {name}…</p>
  } else if (state.status === 'error') {
    const explanation = state.kind === 'missing'
      ? `${name} was not found in ${fileRef.source} or is unavailable. It may have been renamed or removed.`
      : state.kind === 'invalid'
        ? `The link to ${name} is invalid.`
        : `${name} could not be loaded. ${state.message}`
    panel = (
      <div className="document-message document-error" role="alert">
        <p>{explanation}</p>
        <p className="document-actions">
          {state.kind === 'failed' && <button type="button" className="button" onClick={onRetry}>Retry</button>}
          <span>Use Back to folder to return to browsing.</span>
        </p>
      </div>
    )
  } else if (tab === 'rendered') {
    panel = state.document.content === ''
      ? <p className="document-message">This file is empty.</p>
      : <Markdown content={state.document.content} />
  } else {
    panel = (
      <>
        {state.document.content === '' && <p className="document-message">This file is empty.</p>}
        <pre className="document-source" data-testid="document-source" tabIndex={0}>{state.document.content}</pre>
      </>
    )
  }

  return (
    <section
      className="document"
      data-testid="document-view"
      data-hash={state.status === 'ready' ? state.document.hash : undefined}
      aria-labelledby="document-title"
      aria-busy={state.status === 'loading'}
    >
      <header className="document-header">
        <div className="document-identity">
          <h2 id="document-title" ref={headingRef} tabIndex={-1}>{name}</h2>
          <p className="document-meta" data-testid="document-meta">
            <span className="document-source-name">{fileRef.source}</span>
            <span className="document-separator" aria-hidden="true">·</span>
            <span className="document-path">{fileRef.path}</span>
          </p>
        </div>
        <button type="button" className="button" onClick={onBack}>Back to folder</button>
      </header>
      <div className="tabs" role="tablist" aria-label="Document view">
        {TABS.map((candidate, index) => (
          <button
            key={candidate.id}
            ref={element => { tabRefs.current[index] = element }}
            type="button"
            role="tab"
            id={`tab-${candidate.id}`}
            className="tab"
            aria-selected={tab === candidate.id}
            aria-controls="document-panel"
            tabIndex={tab === candidate.id ? 0 : -1}
            onClick={() => setTab(candidate.id)}
            onKeyDown={onTabKeyDown}
          >
            {candidate.label}
          </button>
        ))}
      </div>
      <div className="document-panel" role="tabpanel" id="document-panel" aria-labelledby={`tab-${tab}`}>
        {panel}
      </div>
    </section>
  )
}
import {
  forceCollide,
  forceLink,
  forceManyBody,
  forceSimulation,
  forceX,
  forceY,
  type Simulation,
  type SimulationLinkDatum,
  type SimulationNodeDatum,
} from 'd3-force'
import type { GraphEdge, GraphNode, NodeKind, Source } from './model.ts'

export type Point = { x: number; y: number }

export type SimNode = SimulationNodeDatum & {
  id: string
  kind: NodeKind
  source: Source
  parentId: string | null
  x: number
  y: number
}

type SimLink = SimulationLinkDatum<SimNode> & { source: SimNode; target: SimNode }

/** Drawn radius of each node type; also used to trim edges. */
export const NODE_RADIUS: Record<NodeKind, number> = { source: 30, directory: 20, file: 14 }
/** Personal space for collision avoidance, leaving room for the label below the shape. */
const COLLIDE_RADIUS: Record<NodeKind, number> = { source: 54, directory: 42, file: 34 }
const CHARGE: Record<NodeKind, number> = { source: -700, directory: -380, file: -160 }
/** Each source cluster is gently pulled to its own side so Pi and Claude stay recognisable. */
const SOURCE_ANCHOR: Record<Source, Point> = { Pi: { x: -180, y: 0 }, Claude: { x: 180, y: 0 } }
const ALPHA_MIN = 0.02
const MAX_SYNC_TICKS = 400

function linkDistance(link: SimLink): number {
  if (link.source.kind === 'source') return 130
  return link.target.kind === 'file' ? 80 : 105
}

/**
 * Owns the force simulation and every node position for the session. Positions of hidden nodes are
 * remembered so that expanding, collapsing and refreshing never rearranges unrelated parts of the graph.
 */
export class GraphLayout {
  private readonly nodes = new Map<string, SimNode>()
  private readonly pinned = new Set<string>()
  private readonly simulation: Simulation<SimNode, SimLink>
  private readonly listeners = new Set<() => void>()
  private visibleIds: string[] = []
  private hasLaidOut = false
  private synchronous: boolean

  constructor(options: { synchronous: boolean }) {
    this.synchronous = options.synchronous
    this.simulation = forceSimulation<SimNode>([])
      .stop()
      .alphaMin(ALPHA_MIN)
      .alphaDecay(0.05)
      .force('link', forceLink<SimNode, SimLink>([]).id(node => node.id).distance(linkDistance).strength(0.9))
      .force('charge', forceManyBody<SimNode>().strength(node => CHARGE[node.kind]).distanceMax(520))
      .force('collide', forceCollide<SimNode>().radius(node => COLLIDE_RADIUS[node.kind]).strength(0.9).iterations(2))
      .force('x', forceX<SimNode>(node => SOURCE_ANCHOR[node.source].x).strength(0.03))
      .force('y', forceY<SimNode>(node => SOURCE_ANCHOR[node.source].y).strength(0.03))
      .on('tick', () => this.notify())
      .on('end', () => this.notify())
  }

  /** Synchronous mode settles the layout instantly (reduced motion, tests) instead of animating ticks. */
  setSynchronous(value: boolean) {
    this.synchronous = value
  }

  subscribe(listener: () => void): () => void {
    this.listeners.add(listener)
    return () => { this.listeners.delete(listener) }
  }

  private notify() {
    for (const listener of this.listeners) listener()
  }

  node(id: string): SimNode | undefined {
    return this.nodes.get(id)
  }

  isPinned(id: string): boolean {
    return this.pinned.has(id)
  }

  /** Aligns the simulation with the currently visible nodes. New nodes appear beside their parent. */
  sync(visible: readonly GraphNode[], edges: readonly GraphEdge[]) {
    const previous = this.visibleIds
    const nextIds = visible.map(node => node.id)
    const unchanged = previous.length === nextIds.length && previous.every((id, i) => id === nextIds[i])
    if (unchanged && this.hasLaidOut) return
    const previouslyVisible = new Set(previous)
    const siblingCounter = new Map<string, number>()
    const simNodes: SimNode[] = []
    for (const node of visible) {
      let sim = this.nodes.get(node.id)
      if (!sim) {
        sim = { id: node.id, kind: node.kind, source: node.source, parentId: node.parentId, x: 0, y: 0 }
        this.nodes.set(node.id, sim)
        this.place(sim, siblingCounter)
      } else if (!previouslyVisible.has(node.id) && !this.pinned.has(node.id)) {
        this.place(sim, siblingCounter)
      }
      simNodes.push(sim)
    }
    const links: SimLink[] = []
    for (const edge of edges) {
      const source = this.nodes.get(edge.parentId)
      const target = this.nodes.get(edge.childId)
      if (source && target) links.push({ source, target })
    }
    this.visibleIds = nextIds
    this.simulation.nodes(simNodes)
    this.simulation.force<ReturnType<typeof forceLink<SimNode, SimLink>>>('link')!.links(links)
    // The very first layout has nothing to transition from, so it always settles instantly.
    this.run(this.hasLaidOut ? 0.6 : 1, !this.hasLaidOut)
    this.hasLaidOut = true
  }

  /** Deterministic placement: fan children out on the side of the parent facing away from the grandparent. */
  private place(sim: SimNode, siblingCounter: Map<string, number>) {
    if (sim.parentId === null) {
      const anchor = SOURCE_ANCHOR[sim.source]
      sim.x = anchor.x
      sim.y = anchor.y
      return
    }
    const parent = this.nodes.get(sim.parentId)
    if (!parent) return
    const index = siblingCounter.get(parent.id) ?? 0
    siblingCounter.set(parent.id, index + 1)
    const grandparent = parent.parentId ? this.nodes.get(parent.parentId) : undefined
    const base = grandparent ? Math.atan2(parent.y - grandparent.y, parent.x - grandparent.x) : -Math.PI / 2
    const angle = base + (index * 2.399963) // golden angle keeps siblings spread without randomness
    const distance = 60 + (index % 3) * 18
    sim.x = parent.x + Math.cos(angle) * distance
    sim.y = parent.y + Math.sin(angle) * distance
    sim.vx = 0
    sim.vy = 0
  }

  private run(alpha: number, forceSynchronous = false) {
    this.simulation.alpha(alpha)
    if (this.synchronous || forceSynchronous) {
      this.simulation.stop()
      for (let i = 0; i < MAX_SYNC_TICKS && this.simulation.alpha() > ALPHA_MIN; i += 1) this.simulation.tick()
      this.notify()
    } else {
      this.simulation.restart()
    }
  }

  /** Moves a node while it is being dragged. The node becomes pinned; the rest of the graph waits. */
  drag(id: string, point: Point) {
    const sim = this.nodes.get(id)
    if (!sim) return
    this.simulation.stop()
    sim.x = sim.fx = point.x
    sim.y = sim.fy = point.y
    sim.vx = 0
    sim.vy = 0
    this.pinned.add(id)
    this.notify()
  }

  /** After a drop, neighbours settle around the pinned node. */
  endDrag() {
    this.run(0.3)
  }

  pin(id: string) {
    const sim = this.nodes.get(id)
    if (!sim) return
    sim.fx = sim.x
    sim.fy = sim.y
    this.pinned.add(id)
    this.notify()
  }

  unpin(id: string) {
    const sim = this.nodes.get(id)
    if (!sim || !this.pinned.has(id)) return
    sim.fx = null
    sim.fy = null
    this.pinned.delete(id)
