const MIN_ZOOM = 0.15
const MAX_ZOOM = 3
const DRAG_THRESHOLD = 4
const FIT_PADDING = 70

function clampZoom(k: number) {
  return Math.min(MAX_ZOOM, Math.max(MIN_ZOOM, k))
